        /// <summary>
        /// The named icon as an inline SVG element, hidden from screen readers (the link or button carries the text).
        /// </summary>
        /// <param name="name">An icon name, for example "dashboard" or "calendar".</param>
        /// <param name="size">The width and height in pixels.</param>
        /// <returns>The SVG markup, or nothing for an unknown name.</returns>
        public static IHtmlContent Svg(string name, int size = 20)
        {
            if (!Paths.TryGetValue(name, out var paths))
            {
                return HtmlString.Empty;
            }

            var px = size.ToString(CultureInfo.InvariantCulture);
            return new HtmlString(
                $"<svg class=\"ico\" width=\"{px}\" height=\"{px}\" viewBox=\"0 0 24 24\" aria-hidden=\"true\" focusable=\"false\">{paths}</svg>");
        }
    }
